bool UsedEntryTable::Has(int chara)
{
	return chara >= 0 && chara < kCharaCount;
}

bool UsedEntryTable::IsUsed(int chara, int entry)
{
	if (!Has(chara) || entry < 0 || entry > 255)
		return true;

	return (kUsed[chara][entry >> 3] & (1 << (entry & 7))) != 0;
}
